window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-170e16829af019eb"]={"versions": [{"id": "FIG-170e16829af019eb", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (Blockarchitektur / High-Level Architectural View) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform (Release R17-03 / AP R1.1.0) oberhalb der Ausführungsumgebung (<code>(Virtual) Machine / Hardware</code>).</li>\n<li>Etabliert die Zweiteilung der Plattform-Funktionalitäten in <strong>Adaptive Platform Foundation</strong> (lokale Bibliotheks-/C++-APIs im Prozesskontext bzw. OS-Kernel) und <strong>Adaptive Platform Services</strong> (als eigenständige Prozesse realisierte, serviceorientierte Plattform-Dienste).</li>\n<li>Spezifiziert die Schnittstellenebene <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> als einheitliche Laufzeitschnittstelle für Adaptive Applications (<code>aa</code>) und Non-Platform Services.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Ausführungsdomänen (von unten nach oben)</p>\n<ol class=\"fig-list\">\n<li><strong>(Virtual) Machine / Hardware:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Physische CPU/SoC-Ressourcen (POSIX-kompatible Mehrkernprozessoren, MMU) oder Hypervisor-basierte virtuelle Maschinen (VM/Guest-OS).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Adaptive Platform Foundation (Blau hinterlegt):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Stellt fundamentale Betriebssystem- und Middleware-Primitive bereit; interagiert primär über C++-Sprachbindungen / statisch bzw. dynamisch gelinkte Bibliotheks-APIs im Kontext der Applikationsprozesse:</li>\n<li><strong>Bootloader:</strong> Initialisierung der Hardware und Laden des Kernels (keine direkte ARA-Exposition).</li>\n<li><strong>Operating System:</strong> POSIX-PSE51-konformes Multithreading/Multiprocessing-OS inklusive Speicher- und Prozessisolation.</li>\n<li><strong>Execution Management (EM):</strong> Start/Stopp-Management von Prozessen, Manifest-basiertes Deployment, Maschinenzustands- und Funktionsgruppen-Zustandsverwaltung via API.</li>\n<li><strong>Communication Management (CM):</strong> Serviceorientierte Kommunikation (SOME/IP, IPC, ara::com).</li>\n<li><strong>Logging and Tracing (LOG):</strong> Standardisiertes Logging/Tracing (LT-Protokoll / DLT-Integration) via API.</li>\n<li><strong>Persistency (PER):</strong> Zugriff auf nichtflüchtigen Speicher (Key-Value-Storage, File-Storage) via API.</li>\n<li><strong>Hardware Acceleration:</strong> Standardisierte Schnittstellen für Rechenbeschleuniger (GPU, DSP, NPU / z. B. OpenVX/OpenCL).</li>\n<li><strong>Platform Health Management (PHM):</strong> Überwachung von Aliveness, Deadline und Logical Supervision via API.</li>\n<li><strong>Other Functional Clusters:</strong> Erweiterbare Foundation-Cluster (z. B. Time Synchronization / TS).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Adaptive Platform Services (Grau hinterlegt):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Plattform-Funktionalitäten, die architektonisch als Service-Provider (über ara::com bzw. IPC) instanziiert werden und über Service-Schnittstellen (<code>Service</code>) mit Clients kommunizieren:</li>\n<li><strong>Software Configuration Management (UCM / Software Management):</strong> Update-, Konfigurations- und Paketmanagement.</li>\n<li><strong>Diagnostics (DM):</strong> Diagnoseverwaltung (UDS over IP / DoIP, ISO 14229) und Fault-Memory-Handling.</li>\n<li><strong>Security Management (SM / Crypto / IAM):</strong> Identity- & Access-Management, Schlüsselverwaltung, Krypto-Services.</li>\n<li><strong>Other Adaptive Platform Services:</strong> Zukünftige/optionale standardisierte AP-Dienste.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Abstraktionsgrenze. Setzt sich zusammen aus:</li>\n<li><strong>C++ API Interface (<code>API</code>):</strong> Direkte Header/Bibliotheks-Calls in Foundation-Cluster.</li>\n<li><strong>Service Proxies / Skeletons (<code>Service</code>):</strong> Über <code>Communication Management</code> geroutete Service-Interfaces zu Platform- und Non-Platform-Services.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikationsebene (Gelb hinterlegt):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Application:</strong> Standard-Adaptive-Applications (User-Space-Prozesse).</li>\n<li><strong>Non-platform service:</strong> Kundenspezifische oder Third-Party-Services, die ihrerseits als Service-Provider im Gesamtsystem fungieren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Interaktionspfade</h4>\n<ul class=\"fig-list\">\n<li><strong>Foundation-Interaktion (In-Process / Direct API):</strong></li>\n<li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).</li>\n<li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).</li>\n<li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong></li>\n<li>Find-Service $\\rightarrow$ Subscribe / Offer-Service $\\rightarrow$ Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.</li>\n<li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.</li>\n<li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong></li>\n<li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.</li>\n<li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest $\\rightarrow$ Proxy/Skeleton-Artefakte) unterscheiden.</li>\n<li><strong>Manifest- & Konfigurationspflichten:</strong></li>\n<li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).</li>\n<li><strong>Boot- und Startup-Restriktionen:</strong></li>\n<li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.</li>\n</ul>"}, {"id": "FIG-ce926fc9d8b43da7", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (High-Level Architectural View) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform oberhalb der physischen bzw. virtualisierten Recheneinheit (<code>Machine</code>).</li>\n<li>Strukturiert die Plattform in die beiden Hauptbereiche <strong>Adaptive Platform Foundation</strong> (Bibliotheks- und Kernel-APIs im Prozesskontext) und <strong>Adaptive Platform Services</strong> (serviceorientierte Plattformdienste).</li>\n<li>Spezifiziert die Schnittstellenebene <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> als Abstraktionsschicht für <strong>User Applications</strong> (bestehend aus Standard-Applikationen und anwendungsspezifischen Services).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Ausführungsdomänen (von unten nach oben)</p>\n<ol class=\"fig-list\">\n<li><strong>Machine:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Physische Rechenknoten oder Hypervisor-basierte Instanzen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Adaptive Platform Foundation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Stellt grundlegende Systemdienste und Middleware-Primitiven über standardisierte C++-Schnittstellen (<code>API</code>) bereit:</li>\n<li><strong>Operating System:</strong> POSIX-basiertes Betriebssystem (Prozess- und Speicherisolation).</li>\n<li><strong>Execution Management:</strong> Prozesslebenszyklus- und Zustandsverwaltung.</li>\n<li><strong>Communication Management:</strong> Serviceorientierte Interprozess- und Netzwerkkonfiguration.</li>\n<li><strong>Persistency:</strong> Nichtflüchtiger Datenspeicher.</li>\n<li><strong>Platform Health Management:</strong> Überwachung der Prozessausführung und Deadlines.</li>\n<li><strong>Time Synchronization:</strong> Verteilte Uhrensynchronisation.</li>\n<li><strong>Identity Access Management:</strong> Identitätsprüfung und Zugriffskontrolle.</li>\n<li><strong>Cryptography:</strong> Kryptografische Operationen und Schlüsselverwaltung.</li>\n<li><strong>Logging and Tracing:</strong> Standardisiertes Logging und Tracing.</li>\n<li><strong>REST:</strong> Webservices und HTTP-basierte Schnittstellen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Adaptive Platform Services:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eigenständige Plattform-Dienstprozesse, die über serviceorientierte Kommunikationsschnittstellen (<code>Service</code>) bereitgestellt werden:</li>\n<li><strong>Update & Configuration Management:</strong> Software-Aktualisierung und Paketmanagement.</li>\n<li><strong>Diagnostics:</strong> Fahrzeug- und Systemdiagnose (UDS/DoIP).</li>\n<li><strong>Signal-2-Service Mapping:</strong> Übersetzung zwischen signalbasierten Bussystemen (z. B. CAN/LIN) und serviceorientierten Schnittstellen.</li>\n<li><strong>Network Management:</strong> Koordination des Netzwerkzustands und Kommunikationsbereitschaft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Übergreifende Laufzeitschnittstelle aus direkten C++-APIs (<code>API</code>) und Service-Schnittstellen (<code>Service</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>User Applications:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausführungsebene oberhalb der ARA, unterteilt in klassische adaptive Applikationen (<code>Application</code>) und anwendungsspezifische Nicht-Plattform-Dienste (<code>Non-platform service</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Foundation-Interaktion (In-Process / Direct API):</strong></li>\n<li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).</li>\n<li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).</li>\n<li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong></li>\n<li>Find-Service $\\rightarrow$ Subscribe / Offer-Service $\\rightarrow$ Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.</li>\n<li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.</li>\n<li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong></li>\n<li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.</li>\n<li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest $\\rightarrow$ Proxy/Skeleton-Artefakte) unterscheiden.</li>\n<li><strong>Manifest- & Konfigurationspflichten:</strong></li>\n<li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).</li>\n<li><strong>Boot- und Startup-Restriktionen:</strong></li>\n<li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.</li>\n</ul>"}, {"id": "FIG-99c8ebb58db9d95c", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (High-Level Architectural View) der AUTOSAR Adaptive Platform (AP) mit expliziter Kennzeichnung funktionaler Cluster (FCs).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform über der Basisschicht <code>(Virtual) Machine / Container / Hardware</code>.</li>\n<li>Führt eine standardisierte Taxonomie und Namenskonvention für funktionale Cluster ein: Unterscheidung zwischen Foundation-Clustern (<code>API Platform Foundation FCs</code>, C++-Bibliotheken im Applikationsprozess) und Service-Clustern (<code>SERVICE Platform Service FCs</code>, als eigenständige Serverprozesse via IPC/SOME/IP angesprochen).</li>\n<li>Schnittstellenebene <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> kapselt alle Cluster gegenüber <strong>User Applications</strong> (<code>Adaptive Application</code> und anwendungsdefinierte Nicht-Plattform-Services <code>ASW::* Non-PF Service</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Ausführungsdomänen (von unten nach oben)</p>\n<ol class=\"fig-list\">\n<li><strong>(Virtual) Machine / Container / Hardware:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zugrundeliegende Ausführungsumgebung: Bare-Metal-Hardware, Hypervisor-VMs oder OS-Container.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA) / Platform FCs:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Platform Foundation FCs (über <code>API</code> angebunden):</strong></li>\n<li><strong>POSIX PSE51 / C++ STL (Operating System):</strong> POSIX-Schnittstelle und C++ Standardbibliothek.</li>\n<li><strong>ara::core (Core Types):</strong> Grundlegende Datentypen, Fehlerbehandlung (<code>Result</code>) und Hilfsklassen.</li>\n<li><strong>ara::exec (Execution Mgmt.):</strong> Prozessinitialisierung, Scheduling und Funktionsgruppen.</li>\n<li><strong>ara::com (Communication Mgmt.):</strong> Transportunabhängige Middleware, untergliedert in Transportbindungen <code>SOME/IP</code>, <code>IPC (local)</code> und <code>DDS</code>.</li>\n<li><strong>ara::rest (RESTful):</strong> REST-Client/Server-Konnektivität.</li>\n<li><strong>ara::per (Persistency):</strong> Persistenter Speicher (Key-Value, File).</li>\n<li><strong>ara::tsync (Time Synchronization):</strong> Zeitquellen-Synchronisation.</li>\n<li><strong>ara::phm (Platform Health Mgmt.):</strong> Alive-/Deadline-/Logical-Supervision.</li>\n<li><strong>ara::iam (Identity Access Mgmt.):</strong> Zugriffsrechte und Policy Enforcement.</li>\n<li><strong>ara::log (Logging & Tracing):</strong> Strukturierte Protokollierung.</li>\n<li><strong>ara::crypto (Cryptography):</strong> Krypto-Operationen und Zertifikatsmanagement.</li>\n<li><strong>Platform Service FCs (über <code>SERVICE</code> angebunden):</strong></li>\n<li><strong>ara::sm service (State Management):</strong> Zentrale Steuerung von Systemzuständen und Funktionsgruppen.</li>\n<li><strong>ara::diag service (Diagnostics):</strong> Diagnose-Routing und Fehlerspeicher.</li>\n<li><strong>ara::s2s service (Signal to Service Mapping):</strong> Signal-Service-Gateway für klassische Feldbusse.</li>\n<li><strong>ara::nm service (Network Management):</strong> Bus- und Teilnetzwerk-Management.</li>\n<li><strong>ara::ucm service (Update and Configuration Management):</strong> Paketinstallation und Softwareaktualisierung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>User Applications:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vier Instanzen/Blöcke von <code>Adaptive Application</code>.</li>\n<li>Anwendungsbezogene Services: <code>ASW::XYZ Non-PF Service</code> und <code>ASW::ABC Non-PF Service</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Legende (Legend):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SERVICE Non-PF Service</code> (orange hinterlegt).</li>\n<li><code>SERVICE Platfrom Service FCs</code> (grau hinterlegt mit Service-Balken).</li>\n<li><code>API Platform Foundation FCs</code> (hellblau hinterlegt mit API-Balken).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Foundation-Interaktion (In-Process / Direct API):</strong></li>\n<li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).</li>\n<li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).</li>\n<li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong></li>\n<li>Find-Service $\\rightarrow$ Subscribe / Offer-Service $\\rightarrow$ Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.</li>\n<li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.</li>\n<li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong></li>\n<li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.</li>\n<li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest $\\rightarrow$ Proxy/Skeleton-Artefakte) unterscheiden.</li>\n<li><strong>Manifest- & Konfigurationspflichten:</strong></li>\n<li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).</li>\n<li><strong>Boot- und Startup-Restriktionen:</strong></li>\n<li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.</li>\n</ul>"}, {"id": "FIG-f899d4a45b4135d6", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (High-Level Architectural View) der AUTOSAR Adaptive Platform (AP) mit expliziter Kennzeichnung funktionaler Cluster (FCs).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform über der Basisschicht <code>(Virtual) Machine / Container / Hardware</code>.</li>\n<li>Führt eine standardisierte Taxonomie und Namenskonvention für funktionale Cluster ein: Unterscheidung zwischen Foundation-Clustern (<code>API Platform Foundation FCs</code>, C++-Bibliotheken im Applikationsprozess) und Service-Clustern (<code>SERVICE Platform Service FCs</code>, als eigenständige Serverprozesse via IPC/SOME/IP angesprochen).</li>\n<li>Schnittstellenebene <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> kapselt alle Cluster gegenüber <strong>User Applications</strong> (<code>Adaptive Application</code> und anwendungsdefinierte Nicht-Plattform-Services <code>ASW::* Non-PF Service</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Ausführungsdomänen (von unten nach oben)</p>\n<ol class=\"fig-list\">\n<li><strong>(Virtual) Machine / Container / Hardware:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zugrundeliegende Ausführungsumgebung: Bare-Metal-Hardware, Hypervisor-VMs oder OS-Container.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA) / Platform FCs:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Platform Foundation FCs (über <code>API</code> angebunden):</strong></li>\n<li><strong>POSIX PSE51 / C++ STL (Operating System Interface):</strong> POSIX-Schnittstelle und C++ Standardbibliothek.</li>\n<li><strong>ara::core (Core Types):</strong> Grundlegende Datentypen und Basisfunktionalitäten.</li>\n<li><strong>ara::exec (Execution Management):</strong> Prozesslebenszyklus- und Ausführungssteuerung.</li>\n<li><strong>ara::com (Communication Management.):</strong> Kommunikationsmiddleware mit Bindungen <code>SOME/IP</code>, <code>IPC (local)</code> und <code>DDS</code>.</li>\n<li><strong>ara::rest (RESTful):</strong> REST-Schnittstellen.</li>\n<li><strong>ara::per (Persistency):</strong> Persistente Datenspeicherung.</li>\n<li><strong>ara::tsync (Time Synchronization):</strong> Zeitsynchronisation.</li>\n<li><strong>ara::phm (Platform Health Management):</strong> Plattform-Gesundheits- und Prozessüberwachung.</li>\n<li><strong>ara::iam (Identity and Access Management):</strong> Zugriffskontrolle und Identitätsverwaltung.</li>\n<li><strong>ara::log (Log and Trace):</strong> Logging- und Tracing-Framework.</li>\n<li><strong>ara::crypto (Cryptography):</strong> Kryptografie-Dienste.</li>\n<li><strong>Platform Service FCs (über <code>SERVICE</code> angebunden):</strong></li>\n<li><strong>ara::sm service (State Management):</strong> Zustandsverwaltung und Koordination.</li>\n<li><strong>ara::diag service (Diagnostics):</strong> Diagnoseprotokolle und Fehlermanagement.</li>\n<li><strong>ara::s2s service (Signal to Service Mapping):</strong> Transformation signalbasierter Kommunikation in Services.</li>\n<li><strong>ara::nm service (Network Management):</strong> Netzwerkmanagement.</li>\n<li><strong>ara::ucm service (Update and Config Management):</strong> Software-Update- und Konfigurationsmanagement.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>User Applications:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vier <code>Adaptive Application</code>-Instanzen.</li>\n<li>Nicht-Plattform-Services <code>ASW::XYZ Non-PF Service</code> und <code>ASW::ABC Non-PF Service</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Legende (Key):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SERVICE Non-PF Service</code> (orange).</li>\n<li><code>SERVICE Platform Service FCs</code> (grau).</li>\n<li><code>API Platform Foundation FCs</code> (blau).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Foundation-Interaktion (In-Process / Direct API):</strong></li>\n<li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).</li>\n<li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).</li>\n<li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong></li>\n<li>Find-Service $\\rightarrow$ Subscribe / Offer-Service $\\rightarrow$ Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.</li>\n<li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.</li>\n<li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong></li>\n<li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.</li>\n<li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest $\\rightarrow$ Proxy/Skeleton-Artefakte) unterscheiden.</li>\n<li><strong>Manifest- & Konfigurationspflichten:</strong></li>\n<li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).</li>\n<li><strong>Boot- und Startup-Restriktionen:</strong></li>\n<li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.</li>\n</ul>"}, {"id": "FIG-90d9ec5b03eb9ee3", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (High-Level Architectural View) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform über der Basisschicht <code>(Virtual) Machine / Container / Hardware</code>.</li>\n<li>Weist funktionale Cluster verbindlich den Bereichen <strong>Platform Foundation FCs</strong> (<code>API</code>, C++-Bibliotheken) und <strong>Platform Service FCs</strong> (<code>SERVICE</code>, eigenständige Prozesse via IPC/SOME/IP) zu.</li>\n<li>Stellt die <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> als Abstraktionsebene für <strong>User Applications</strong> bereit, wobei Signal-to-Service-Transformation als Protokollbindung (<code>Signal PDU</code>) direkt in <code>ara::com</code> integriert und Diagnose (<code>ara::diag</code>) als Foundation-Cluster modelliert ist.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Ausführungsdomänen (von unten nach oben)</p>\n<ol class=\"fig-list\">\n<li><strong>(Virtual) Machine / Container / Hardware:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Physische oder virtualisierte Plattform (Bare-Metal, VM, Container).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA) / Platform FCs:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Platform Foundation FCs (über <code>API</code> angebunden):</strong></li>\n<li><strong>POSIX PSE51 / C++ STL (Operating System Interface):</strong> Betriebssystemschnittstelle nach POSIX PSE51 und C++ Standardbibliothek.</li>\n<li><strong>ara::core (Core Types):</strong> Grundlegende Typen und Primitive.</li>\n<li><strong>ara::exec (Execution Management):</strong> Zustands-, Prozess- und Ressourcenverwaltung.</li>\n<li><strong>ara::com (Communication Management.):</strong> Kommunikationsmiddleware mit den Transport- und Protokollbindungen <code>IPC</code>, <code>Signal PDU</code>, <code>SOME/IP</code> und <code>DDS</code>.</li>\n<li><strong>ara::rest (RESTful):</strong> RESTful Web-Services.</li>\n<li><strong>ara::per (Persistency):</strong> Persistente Datenspeicherung.</li>\n<li><strong>ara::tsync (Time Synchronization):</strong> Uhrensynchronisation.</li>\n<li><strong>ara::phm (Platform Health Management):</strong> Health Monitoring und Überwachungsfunktionen.</li>\n<li><strong>ara::diag (Diagnostics):</strong> Diagnoseschnittstelle im Prozesskontext der Applikation.</li>\n<li><strong>ara::iam (Identity and Access Management):</strong> Autorisierung und Richtliniendurchsetzung.</li>\n<li><strong>ara::log (Log and Trace):</strong> Diagnose- und Entwicklungs-Logging/-Tracing.</li>\n<li><strong>ara::crypto (Cryptography):</strong> Kryptografische Primitive und Schlüsselverwaltung.</li>\n<li><strong>Platform Service FCs (über <code>SERVICE</code> angebunden):</strong></li>\n<li><strong>ara::sm service (State Management):</strong> Globales System- und Funktionsgruppen-Zustandsmanagement.</li>\n<li><strong>ara::ucm service (Update and Config Management):</strong> Paket-, Software- und Update-Management.</li>\n<li><strong>ara::nm service (Network Management):</strong> Netzwerk-Zustandsmanagement.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>User Applications:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Drei <code>Adaptive Application</code>-Instanzen.</li>\n<li>Nicht-Plattform-Services <code>ASW::XYZ Non-PF Service</code> und <code>ASW::ABC Non-PF Service</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Legende (Key):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SERVICE Non-PF Service</code> (orange).</li>\n<li><code>SERVICE Platform Service FCs</code> (grau).</li>\n<li><code>API Platform Foundation FCs</code> (blau).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Foundation-Interaktion (In-Process / Direct API):</strong></li>\n<li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).</li>\n<li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).</li>\n<li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong></li>\n<li>Find-Service $\\rightarrow$ Subscribe / Offer-Service $\\rightarrow$ Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.</li>\n<li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.</li>\n<li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong></li>\n<li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.</li>\n<li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest $\\rightarrow$ Proxy/Skeleton-Artefakte) unterscheiden.</li>\n<li><strong>Manifest- & Konfigurationspflichten:</strong></li>\n<li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).</li>\n<li><strong>Boot- und Startup-Restriktionen:</strong></li>\n<li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.</li>\n</ul>"}, {"id": "FIG-d642ff7e58895e5c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (High-Level Architectural View) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform über der Basisschicht <code>(Virtual) Machine / Container / Hardware</code>.</li>\n<li>Weist funktionale Cluster verbindlich den Bereichen <strong>Platform Foundation FCs</strong> (<code>API</code>, C++-Bibliotheken) und <strong>Platform Service FCs</strong> (<code>SERVICE</code>, eigenständige Prozesse via IPC/SOME/IP) zu.</li>\n<li>Stellt die <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> als Abstraktionsebene für <strong>User Applications</strong> bereit, wobei Signal-to-Service-Transformation als Protokollbindung (<code>Signal PDU</code>) direkt in <code>ara::com</code> integriert und Diagnose (<code>ara::diag</code>) als Foundation-Cluster modelliert ist.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Ausführungsdomänen (von unten nach oben)</p>\n<ol class=\"fig-list\">\n<li><strong>(Virtual) Machine / Container / Hardware:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Physische oder virtualisierte Plattform (Bare-Metal, VM, Container).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA) / Platform FCs:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Platform Foundation FCs (über <code>API</code> angebunden):</strong></li>\n<li><strong>POSIX PSE51 / C++ STL (Operating System Interface):</strong> POSIX PSE51 und C++ STL Betriebssystemschnittstelle.</li>\n<li><strong>ara::core (Core):</strong> Basistypen und Kernprimitive der Adaptive Platform.</li>\n<li><strong>ara::exec (Execution Management):</strong> Start, Stopp und Überwachung von Prozessen.</li>\n<li><strong>ara::com (Communication Management.):</strong> Serviceorientierte Kommunikation mit Bindungen <code>IPC</code>, <code>Signal PDU</code>, <code>SOME/IP</code> und <code>DDS</code>.</li>\n<li><strong>ara::rest (REST):</strong> REST-Webservices.</li>\n<li><strong>ara::per (Persistency):</strong> Nichtflüchtige Datenspeicherung.</li>\n<li><strong>ara::tsync (Time Synchronization):</strong> Synchronisation von Zeitbasen.</li>\n<li><strong>ara::phm (Platform Health Management):</strong> Alive-, Deadline- und logische Überwachung.</li>\n<li><strong>ara::diag (Diagnostics):</strong> Diagnoseschnittstelle.</li>\n<li><strong>ara::iam (Identity and Access Management):</strong> Identitäts- und Rechtemanagement.</li>\n<li><strong>ara::log (Log and Trace):</strong> Logging und Tracing.</li>\n<li><strong>ara::crypto (Cryptography):</strong> Kryptografische Algorithmen und Zertifikate.</li>\n<li><strong>Platform Service FCs (über <code>SERVICE</code> angebunden):</strong></li>\n<li><strong>ara::sm service (State Management):</strong> Plattformweites Zustandsmanagement.</li>\n<li><strong>ara::ucm service (Update and Config Management):</strong> Update- und Konfigurationsverwaltung.</li>\n<li><strong>ara::nm service (Network Management):</strong> Netzwerkmanagement.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>User Applications:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Drei <code>Adaptive Application</code>-Instanzen.</li>\n<li>Nicht-Plattform-Services <code>ASW::XYZ Non-PF Service</code> und <code>ASW::ABC Non-PF Service</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Legende (Key):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SERVICE Non-PF Service</code> (orange).</li>\n<li><code>SERVICE Platform Service FCs</code> (grau).</li>\n<li><code>API Platform Foundation FCs</code> (blau).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Foundation-Interaktion (In-Process / Direct API):</strong></li>\n<li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).</li>\n<li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).</li>\n<li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong></li>\n<li>Find-Service $\\rightarrow$ Subscribe / Offer-Service $\\rightarrow$ Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.</li>\n<li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.</li>\n<li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong></li>\n<li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.</li>\n<li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest $\\rightarrow$ Proxy/Skeleton-Artefakte) unterscheiden.</li>\n<li><strong>Manifest- & Konfigurationspflichten:</strong></li>\n<li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).</li>\n<li><strong>Boot- und Startup-Restriktionen:</strong></li>\n<li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.</li>\n</ul>"}], "trans": [{"from": "FIG-170e16829af019eb", "to": "FIG-ce926fc9d8b43da7", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>User Applications:</strong> Explizite Zusammenfassung der oberen Ebene unter der Bereichsbezeichnung <code>User Applications</code> (zuvor unbeschrifteter gelber Bereich).</li>\n<li><strong>Adaptive Platform Foundation:</strong></li>\n<li>Hinzugefügt: <code>REST</code> (mit <code>API</code>), <code>Identity Access Management</code> (mit <code>API</code>), <code>Cryptography</code> (mit <code>API</code>) und <code>Time Synchronization</code> (mit <code>API</code>).</li>\n<li>Entfallen: <code>Hardware Acceleration</code>, <code>Other Functional Clusters</code> und <code>Bootloader</code>.</li>\n<li><strong>Adaptive Platform Services:</strong></li>\n<li>Hinzugefügt: <code>Signal-2-Service Mapping</code> (mit <code>Service</code>) und <code>Network Management</code> (mit <code>Service</code>).</li>\n<li>Umbenannt: <code>Software Configuration Management</code> in <code>Update &amp; Configuration Management</code>.</li>\n<li>Entfallen: <code>Other Adaptive Platform Services</code> sowie <code>Security Management</code> (aufgeteilt in IAM und Cryptography in der Foundation).</li>\n<li><strong>Infrastruktur / Hardware:</strong> Umbenennung der Basisschicht von <code>(Virtual) Machine / Hardware</code> zu <code>Machine</code>.</li>\n</ul>"}, {"from": "FIG-ce926fc9d8b43da7", "to": "FIG-99c8ebb58db9d95c", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Legende:</strong> Hinzufügung einer Legende (<code>Legend</code>) zur Unterscheidung von <code>SERVICE Non-PF Service</code>, <code>SERVICE Platfrom Service FCs</code> und <code>API Platform Foundation FCs</code>.</li>\n<li><strong>Applikationsebene:</strong> Erweiterung auf vier <code>Adaptive Application</code>-Blöcke sowie Spezifikation der Non-Platform-Services als <code>ASW::XYZ Non-PF Service</code> und <code>ASW::ABC Non-PF Service</code>.</li>\n<li><strong>Adaptive Platform Foundation:</strong></li>\n<li>Einführung von Namespace-Präfixen: <code>ara::core Core Types</code>, <code>ara::com Communication Mgmt.</code>, <code>ara::rest RESTful</code>, <code>ara::tsync Time Synchronization</code>, <code>ara::per Persistency</code>, <code>ara::phm Platform Health Mgmt.</code>, <code>ara::exec Execution Mgmt.</code>, <code>ara::iam Identity Access Mgmt.</code>, <code>ara::log Logging &amp; Tracing</code>, <code>ara::crypto Cryptography</code>.</li>\n<li>Detaillierung von <code>ara::com</code>: Vertikale Unterteilung in Transportbindungen <code>SOME/IP</code>, <code>IPC (local)</code> und <code>DDS</code>.</li>\n<li>Umbenennung des Betriebssystems zu <code>POSIX PSE51 / C++ STL Operating System</code>.</li>\n<li><strong>Adaptive Platform Services:</strong></li>\n<li>Einführung von Namespace- und Servicemarkern: <code>ara::sm service State Management</code> (ersetzt EM-Zustandsverwaltung als separater Plattform-Service), <code>ara::diag service Diagnostics</code>, <code>ara::s2s service Signal to Service Mapping</code>, <code>ara::nm service Network Management</code>, <code>ara::ucm service Update and Configuration Management</code>.</li>\n<li><strong>Basisschicht:</strong> Umbenennung von <code>Machine</code> zu <code>(Virtual) Machine / Container / Hardware</code>.</li>\n</ul>"}, {"from": "FIG-99c8ebb58db9d95c", "to": "FIG-f899d4a45b4135d6", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Legende:</strong> Umbenennung der Überschrift von <code>Legend</code> zu <code>Key</code> sowie Korrektur des Tippfehlers in <code>Platfrom Service FCs</code> zu <code>Platform Service FCs</code>.</li>\n<li><strong>Beschriftungen:</strong></li>\n<li>Foundation: <code>ara::iam Identity Access Mgmt.</code> umbenannt in <code>ara::iam Identity and Access Management</code>; <code>ara::log Logging &amp; Tracing</code> umbenannt in <code>ara::log Log and Trace</code>; <code>POSIX PSE51 / C++ STL Operating System</code> umbenannt in <code>POSIX PSE51 / C++ STL Operating System Interface</code>.</li>\n<li>Platform Services: <code>ara::ucm service Update and Configuration Management</code> umbenannt in <code>ara::ucm service Update and Config Management</code>.</li>\n<li><strong>Layout:</strong> Entfernung des oberen Textfragments am Bildrand.</li>\n</ul>"}, {"from": "FIG-f899d4a45b4135d6", "to": "FIG-90d9ec5b03eb9ee3", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Applikationsebene:</strong> Reduktion der <code>Adaptive Application</code>-Kacheln von vier auf drei.</li>\n<li><strong>Verschiebung Diagnostics:</strong> <code>ara::diag Diagnostics</code> wechselt von den Platform Services (<code>SERVICE</code>) in die Adaptive Platform Foundation (<code>API</code>).</li>\n<li><strong>Entfall Signal to Service Mapping:</strong> Das Cluster <code>ara::s2s service Signal to Service Mapping</code> entfällt als eigenständiger Platform Service; stattdessen wird <code>Signal PDU</code> als Bindung/Interface direkt in <code>ara::com</code> integriert (neben <code>IPC</code>, <code>SOME/IP</code> und <code>DDS</code>).</li>\n<li><strong>Anordnung:</strong> <code>ara::sm service</code>, <code>ara::ucm service</code> und <code>ara::nm service</code> bilden nun die verbleibenden Platform Services. Foundation-Cluster werden im Raster neu angeordnet (<code>ara::diag</code>, <code>ara::log</code>, <code>ara::crypto</code>).</li>\n</ul>"}, {"from": "FIG-90d9ec5b03eb9ee3", "to": "FIG-d642ff7e58895e5c", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>ara::core:</strong> Beschriftung von <code>ara::core Core Types</code> geändert zu <code>ara::core Core</code>.</li>\n<li><strong>ara::rest:</strong> Beschriftung von <code>ara::rest RESTful</code> geändert zu <code>ara::rest REST</code>.</li>\n</ul>"}]};
